import { useState } from 'react'
import DatePicker from '@/components/ui/DatePicker'

const Controlled = () => {
    const [date, setDate] = (useState < Date) | (null > new Date())
    const [dateRange, setDateRange] =
        useState <
        [Date | null, Date | null] >
        [new Date(2022, 11, 1), new Date(2022, 11, 5)]
    const [dateTime, setDateTime] = (useState < Date) | (null > new Date())

    const handleDatePickerChange = (date: Date | null) => {
        console.log('Selected date', date)
        setDate(date)
    }

    const handleRangePickerChange = (date: [Date | null, Date | null]) => {
        console.log('Selected range date', date)
        setDateRange(date)
    }

    const handleDateTimeChange = (val: Date | null) => {
        console.log('Selected date time: ', val)
        setDateTime(val)
    }

    return (
        <div className="flex flex-col gap-5">
            <DatePicker
                placeholder="Pick a date"
                value={date}
                onChange={handleDatePickerChange}
            />
            <DatePicker.DatePickerRange
                placeholder="Select dates range"
                value={dateRange}
                onChange={handleRangePickerChange}
            />
            <DatePicker.DateTimepicker
                placeholder="Pick date & time"
                value={dateTime}
                onChange={handleDateTimeChange}
            />
        </div>
    )
}

export default Controlled
import DatePicker from '@/components/ui/DatePicker'
import dayjs from 'dayjs'

const DisableOutOfRangeDate = () => {
    const dateGap = 7

    // Only able to select previos & future 7 days start from today
    const minDate = dayjs(new Date())
        .subtract(dateGap, 'day')
        .startOf('day')
        .toDate()
    const maxDate = dayjs(new Date()).add(dateGap, 'day').toDate()

    return (
        <DatePicker
            placeholder="Pick a date"
            minDate={minDate}
            maxDate={maxDate}
        />
    )
}

export default DisableOutOfRangeDate
import { useState } from 'react'
import DatePicker from '@/components/ui/DatePicker'

const DisabledCertainDate = () => {
    const [dateValue, setDateValue] = useState<Date>(new Date())

    const onCertainPeriodChange = (date: Date) => {
        setDateValue(date)
    }

    const disableCertainDate = (date: Date) => {
        const banDate = [7, 15, 21]
        return banDate.includes(date.getDate())
    }

    return (
        <DatePicker
            value={dateValue}
            placeholder="Pick your date"
            disableDate={disableCertainDate}
            onChange={(date) => onCertainPeriodChange(date as Date)}
        />
    )
}

export default DisabledCertainDate
